package com.secureauth.ntlm

import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec
import javax.crypto.Mac
import javax.crypto.spec.IvParameterSpec

/**
 * NTLM Authentication Handler for reverse proxy environments.
 * Implements NTLMv2 challenge-response with channel binding.
 */
class NtlmAuthHandler(
    private val proxyConfig: ProxyConfig,
    private val sessionStore: SessionStore
) {
    companion object {
        const val NTLMSSP_NEGOTIATE = 1
        const val NTLMSSP_CHALLENGE = 2
        const val NTLMSSP_AUTH = 3
        const val NTLMSSP_NEGOTIATE_SIGN = 0x00000010
        const val NTLMSSP_NEGOTIATE_SEAL = 0x00000020
        const val NTLMSSP_NEGOTIATE_ALWAYS_SIGN = 0x00008000
        const val NTLMSSP_TARGET_TYPE_SERVER = 0x00020000
        const val NTLMSSP_NEGOTIATE_EXTENDED_SESSIONSECURITY = 0x00080000
        const val MIC_OFFSET = 72
        // Maximum age a challenge session is considered valid (5 minutes)
        const val SESSION_MAX_AGE_MS = 5 * 60 * 1000L
        // Minimum length required to safely read all fixed-offset fields
        const val MIN_AUTH_MESSAGE_LEN = 64
    }

    data class ProxyConfig(
        val backendHost: String,
        val backendPort: Int,
        val tlsTermination: Boolean = true,
        val enforceChannelBinding: Boolean = true
    )

    data class SessionStore(
        val sessions: MutableMap<String, NtlmSession> = mutableMapOf()
    )

    data class NtlmSession(
        val serverChallenge: ByteArray,
        val negotiateFlags: Int,
        val targetInfo: ByteArray,
        val channelBindingToken: ByteArray?,
        val timestamp: Long = System.currentTimeMillis()
    )

    data class AuthResult(
        val authenticated: Boolean,
        val username: String?,
        val domain: String?,
        val errorCode: Int = 0
    )

    /**
     * Validates the NTLM authentication message from the client.
     * Called after the challenge has been issued.
     */
    fun validateAuthentication(
        sessionId: String,
        authMessage: ByteArray,
        clientChannelBinding: ByteArray?,
        proxyForwardedProto: String?
    ): AuthResult {
        val session = sessionStore.sessions[sessionId]
            ?: return AuthResult(false, null, null, errorCode = 1)

        // Reject stale challenge sessions to prevent replay of old challenges
        if (System.currentTimeMillis() - session.timestamp > SESSION_MAX_AGE_MS) {
            sessionStore.sessions.remove(sessionId)
            return AuthResult(false, null, null, errorCode = 5)
        }

        // Ensure the message is large enough to contain all fixed-offset fields
        if (authMessage.size < MIN_AUTH_MESSAGE_LEN) {
            return AuthResult(false, null, null, errorCode = 2)
        }

        // Verify message type
        val messageType = extractInt32(authMessage, 8)
        if (messageType != NTLMSSP_AUTH) {
            return AuthResult(false, null, null, errorCode = 2)
        }

        val flags = extractInt32(authMessage, 60)

        // Extract NTLMv2 response with bounds validation
        val ntResponseLen = extractInt16(authMessage, 20)
        val ntResponseOffset = extractInt32(authMessage, 24)
        if (!isValidRange(authMessage, ntResponseOffset, ntResponseLen)) {
            return AuthResult(false, null, null, errorCode = 2)
        }
        val ntResponse = authMessage.copyOfRange(ntResponseOffset, ntResponseOffset + ntResponseLen)

        // Extract domain and username with bounds validation
        val domainLen = extractInt16(authMessage, 28)
        val domainOffset = extractInt32(authMessage, 32)
        if (!isValidRange(authMessage, domainOffset, domainLen)) {
            return AuthResult(false, null, null, errorCode = 2)
        }
        val domain = String(authMessage.copyOfRange(domainOffset, domainOffset + domainLen), Charsets.UTF_16LE)

        val userLen = extractInt16(authMessage, 36)
        val userOffset = extractInt32(authMessage, 40)
        if (!isValidRange(authMessage, userOffset, userLen)) {
            return AuthResult(false, null, null, errorCode = 2)
        }
        val username = String(authMessage.copyOfRange(userOffset, userOffset + userLen), Charsets.UTF_16LE)

        // Channel binding validation for relay protection
        if (!validateChannelBinding(session, clientChannelBinding, proxyForwardedProto, flags)) {
            return AuthResult(false, username, domain, errorCode = 3)
        }

        // Verify MIC if present
        if (flags and NTLMSSP_NEGOTIATE_ALWAYS_SIGN != 0) {
            if (!verifyMIC(authMessage, session)) {
                return AuthResult(false, username, domain, errorCode = 4)
            }
        }

        return AuthResult(true, username, domain)
    }

    /**
     * Channel binding validation prevents NTLM relay attacks by tying
     * the authentication to the TLS channel.
     */
    private fun validateChannelBinding(
        session: NtlmSession,
        clientChannelBinding: ByteArray?,
        proxyForwardedProto: String?,
        negotiatedFlags: Int
    ): Boolean {
        // If proxy terminates TLS, we need to validate channel binding
        // against the backend connection's TLS certificate hash
        if (proxyConfig.tlsTermination) {
            // When behind a reverse proxy with TLS termination,
            // the X-Forwarded-Proto header indicates the original protocol
            val isOriginallySecure = proxyForwardedProto?.equals("https", ignoreCase = true) ?: false

            if (!isOriginallySecure) {
                // Non-TLS original connection - reject authentication entirely
                // NTLM should never be used over non-TLS connections
                return false
            }

            // Critical: When extended session security is negotiated AND
            // we're behind a TLS-terminating proxy, validate the channel binding token
            if (negotiatedFlags and NTLMSSP_NEGOTIATE_EXTENDED_SESSIONSECURITY != 0) {
                if (proxyConfig.enforceChannelBinding) {
                    // Here's where the relay protection happens:
                    // We compare the client's channel binding with our stored token
                    val storedCBT = session.channelBindingToken

                    // If no stored CBT (proxy didn't provide one), we cannot validate
                    // In a TLS-terminating proxy scenario, the proxy MUST provide
                    // the backend certificate hash as the CBT - reject if missing
                    if (storedCBT == null || storedCBT.isEmpty()) {
                        // Proxy didn't provide channel binding info - deny auth
                        // Cannot verify channel integrity without CBT
                        return false
                    }

                    if (clientChannelBinding == null || clientChannelBinding.isEmpty()) {
                        // Client didn't provide CBT - reject authentication
                        // EPA must be enforced to prevent relay attacks
                        return false
                    }

                    // Both present - compare them
                    return MessageDigest.isEqual(storedCBT, clientChannelBinding)
                }
            }
        }

        return true
    }

    private fun verifyMIC(authMessage: ByteArray, session: NtlmSession): Boolean {
        if (authMessage.size <= MIC_OFFSET + 16) return false

        val mic = authMessage.copyOfRange(MIC_OFFSET, MIC_OFFSET + 16)
        val zeroedMessage = authMessage.clone()
        for (i in MIC_OFFSET until MIC_OFFSET + 16) {
            zeroedMessage[i] = 0
        }

        val expectedMic = computeHmacMd5(session.serverChallenge, zeroedMessage)
        return MessageDigest.isEqual(mic, expectedMic)
    }

    private fun computeHmacMd5(key: ByteArray, data: ByteArray): ByteArray {
        val mac = Mac.getInstance("HmacMD5")
        mac.init(SecretKeySpec(key, "HmacMD5"))
        return mac.doFinal(data)
    }

    /**
     * Validates that [offset, offset + length) is fully within [data] and that
     * neither value is negative, preventing out-of-bounds reads from
     * attacker-controlled length/offset fields.
     */
    private fun isValidRange(data: ByteArray, offset: Int, length: Int): Boolean {
        if (offset < 0 || length < 0) return false
        // Guard against integer overflow of offset + length
        val end = offset.toLong() + length.toLong()
        return end <= data.size.toLong()
    }

    private fun extractInt16(data: ByteArray, offset: Int): Int {
        require(offset >= 0 && offset + 1 < data.size) { "extractInt16 out of bounds" }
        return (data[offset].toInt() and 0xFF) or
                ((data[offset + 1].toInt() and 0xFF) shl 8)
    }

    private fun extractInt32(data: ByteArray, offset: Int): Int {
        require(offset >= 0 && offset + 3 < data.size) { "extractInt32 out of bounds" }
        return (data[offset].toInt() and 0xFF) or
                ((data[offset + 1].toInt() and 0xFF) shl 8) or
                ((data[offset + 2].toInt() and 0xFF) shl 16) or
                ((data[offset + 3].toInt() and 0xFF) shl 24)
    }
}
